# Retired on 26 Oct 2026 (wave 1b): payload-field keys no GOLD view renders. validate_learn.py check 9 fails on a field
# key that no ui/ source references, so these left tooltips.json instead of lying there unattached. Re-add a line to T the
# day a view renders the field (build() refuses a key that is in both lists):
#   us10y · dfii10 · dgs10 · dtwexbgs      FRED codes; MACRO keys its tips by driver (tips10, dxy, …), not by FRED series
#   mm_long · mm_short                     POSITIONING renders the per-group arrays, not these two scalars
#   observed_expiries · computed_expiries  CONTRACTS' expiries carry a `source` field instead
#   eligible_oz · pledged_oz               the warehouse panel is a link; only `registered_oz` is referenced by a view
#   etf_flow_usd · ibja_995 · mcx_ibja_basis · tariff_value · implied_lease · tender_cutoff   no view prints them yet
#   carry_adj_basis_pct · cot_next_release · fbil_rate · gpr_ratio   (4 Nov 2026) listed in the UI copy's `ui_added` but referenced
#                                          by no view, no router and not in API_CONTRACT.md: retired on the merge, not carried
RETIRED_FIELD_KEYS: tuple[str, ...] = (
    "us10y", "dfii10", "dgs10", "dtwexbgs", "mm_long", "mm_short", "observed_expiries", "computed_expiries",
    "eligible_oz", "pledged_oz", "etf_flow_usd", "ibja_995", "mcx_ibja_basis", "tariff_value", "implied_lease", "tender_cutoff",
    "carry_adj_basis_pct", "cot_next_release", "fbil_rate", "gpr_ratio",
    "sge_vwap",  # (5 Nov 2026, wave 1c) PHYSICAL's Shanghai panel prints the SGE PM, $/oz and the premium; no view prints the VWAP
)

MAX_LEN = 200


def build() -> tuple[list[dict[str, object]], dict[str, str]]:
    """Validate the tables and return (glossary rows, merged tooltips). Raises AssertionError on a defect."""
    terms = [t for t, _, _, _ in G]
    assert len(terms) == len(set(terms)), "duplicate glossary term"
    rows: list[dict[str, object]] = []
    bare = {t.lower().split(" (")[0] for t in terms} | {t.lower() for t in terms}
    seen_alias: dict[str, str] = {}
    for term, aliases in ALIASES.items():
        assert term in terms, ("alias for unknown term", term)
        for alias in aliases:
            key = alias.strip().lower()
            assert key and len(alias) <= 40 and "\n" not in alias, (term, alias)
            assert key not in bare, ("alias equals a term", term, alias)
            assert key not in seen_alias, ("alias used twice", alias, seen_alias.get(key), term)
            seen_alias[key] = term
    for pinned in START_HERE:
        assert pinned in terms, ("start_here names no term", pinned)
    assert len(START_HERE) == len(set(START_HERE)), "start_here repeats a term"
    for term, short, long, see in G:
        assert 0 < len(short) <= MAX_LEN and "\n" not in short, (term, len(short))
        assert long != short, (term, "long repeats short: leave it empty instead")
        for ref in see:
            assert ref in terms, (term, ref)
            assert ref != term, (term, "self reference")
        rows.append({"term": term, "short": short, "long": long, "see_also": see, "aliases": list(ALIASES.get(term, []))})
    overlap = set(T) & set(PANELS)
    assert not overlap, f"tooltip key used as both field and panel: {sorted(overlap)}"
    back = set(T) & set(RETIRED_FIELD_KEYS)
    assert not back, f"retired tooltip key is back in T; drop it from RETIRED_FIELD_KEYS: {sorted(back)}"
    merged = {**T, **PANELS}
    for key, text in merged.items():
        assert 0 < len(text) <= MAX_LEN and "\n" not in text, (key, len(text))
    return rows, merged


def main() -> None:
    rows, merged = build()
    (HERE / "glossary.json").write_text(json.dumps({"version": "2026-11-05", "agent": "G-EDU", "count": len(rows), "start_here": START_HERE,
                                                    "terms": rows}, indent=1, ensure_ascii=False), encoding="utf-8")
    (HERE / "tooltips.json").write_text(json.dumps({"version": "2026-11-05", "agent": "G-EDU", "count": len(merged),
                                                    "note": "keys = app payload fields (PLAN §d) or GOLD panel ids (PLAN §a, listed in `panels`); values ≤ 1 line",
                                                    "panels": sorted(PANELS), "tooltips": merged}, indent=1, ensure_ascii=False), encoding="utf-8")
    n_alias = sum(len(v) for v in ALIASES.values())
    print(f"glossary: {len(rows)} terms, {n_alias} aliases, {len(START_HERE)} start-here; tooltips: {len(T)} fields + {len(PANELS)} panels; "
          f"longest short: {max(len(s) for _, s, _, _ in G)}")


if __name__ == "__main__":
    main()
